{"implementation": "def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    core = payload['core_distance']
    dist_list = payload['distances']
    edges = []
    for u, v, d in dist_list:
        if u > v:
            u, v = v, u
        w = max(core[u], core[v], d)
        edges.append((w, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    selected = []
    total = 0.0
    for w, u, v in edges:
        if union(u, v):
            selected.append([u, v, w])
            total += w
            if len(selected) == len(nodes) - 1:
                break
    if len(selected) != len(nodes) - 1:
        return {'error': 'disconnected graph'}
    return {'edges': selected, 'total_weight': total}"}
